import * as THREE from 'three';

const TAU = Math.PI * 2;

// Sidereal orbital periods in Earth years.
export const PLANETS = [
  { name: 'Mercury', period: 0.241, radius: 2.0 },
  { name: 'Venus', period: 0.615, radius: 3.0 },
  { name: 'Earth', period: 1.0, radius: 4.0 },
  { name: 'Mars', period: 1.881, radius: 5.5 },
];

const ARM_MATERIAL = new THREE.MeshStandardMaterial({ color: 0x888888 });
const PLANET_COLORS = {
  Mercury: 0x9c8e7e,
  Venus: 0xd9b26a,
  Earth: 0x3f6fb5,
  Mars: 0xc1553d,
};
const PLANET_SIZE = 0.25;

/**
 * Build the orrery scene graph:
 *   group
 *   ├─ base (cylinder)
 *   ├─ sun (sphere at the origin)
 *   └─ one arm Group per planet
 *        ├─ thin box from the center outward
 *        └─ planet sphere at the arm's end (local x = radius)
 *
 * Each arm Group carries userData: { planet, period, radius }, so the
 * gearing survives THREE serialization round-trips.
 */
export function buildOrrery() {
  const group = new THREE.Group();
  group.name = 'orrery';

  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(6.5, 7, 0.3, 48),
    new THREE.MeshStandardMaterial({ color: 0x22262b })
  );
  base.name = 'base';
  base.position.y = -0.65;
  group.add(base);

  const sun = new THREE.Mesh(
    new THREE.SphereGeometry(0.8, 32, 24),
    new THREE.MeshStandardMaterial({ color: 0xffc21a, emissive: 0x996600 })
  );
  sun.name = 'sun';
  group.add(sun);

  const arms = [];
  for (const p of PLANETS) {
    const arm = new THREE.Group();
    arm.name = `arm-${p.name}`;
    arm.userData = { planet: p.name, period: p.period, radius: p.radius };

    // Thin box spanning local x in [0, radius].
    const rod = new THREE.Mesh(new THREE.BoxGeometry(p.radius, 0.05, 0.05), ARM_MATERIAL);
    rod.position.x = p.radius / 2;
    arm.add(rod);

    const planet = new THREE.Mesh(
      new THREE.SphereGeometry(PLANET_SIZE, 24, 16),
      new THREE.MeshStandardMaterial({ color: PLANET_COLORS[p.name] })
    );
    planet.name = `planet-${p.name}`;
    planet.position.x = p.radius;
    arm.add(planet);

    group.add(arm);
    arms.push({ name: p.name, period: p.period, radius: p.radius, node: arm });
  }

  return {
    group,
    arms,
    planets: PLANETS,
    setYears(years) {
      setYears(this, years);
    },
    toJSON() {
      return this.group.toJSON();
    },
  };
}

/**
 * Wind the orrery forward by `years` Earth years. Pure function of `years`:
 * every arm's rotation.y is assigned directly as TAU * years / period, so
 * repeated calls never accumulate state.
 */
export function setYears(orrery, years) {
  for (const arm of orrery.arms) {
    arm.node.rotation.y = (TAU * years) / arm.period;
  }
}

