import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildOrrery, setYears, PLANETS } from '../src/orrery.js';

const TAU = Math.PI * 2;
const EPS = 1e-9;

describe('orrery', () => {
  it('puts Earth\'s arm at 2PI after one year', () => {
    const o = buildOrrery();
    setYears(o, 1);
    const earth = o.arms.find((a) => a.name === 'Earth');
    expect(earth.node.rotation.y).toBeCloseTo(TAU, 9); // within 1e-9
    expect(Math.abs(earth.node.rotation.y - TAU)).toBeLessThan(1e-9);
  });

  it('puts Mercury\'s arm at 2PI / 0.241 after one year', () => {
    const o = buildOrrery();
    setYears(o, 1);
    const mercury = o.arms.find((a) => a.name === 'Mercury');
    const expected = TAU / 0.241;
    expect(Math.abs(mercury.node.rotation.y - expected)).toBeLessThan(1e-9);
  });

  it('matches the closed-form Earth-Mars angular difference at y = 0.5', () => {
    const o = buildOrrery();
    setYears(o, 0.5);
    const earth = o.arms.find((a) => a.name === 'Earth').node.rotation.y;
    const mars = o.arms.find((a) => a.name === 'Mars').node.rotation.y;
    // Closed form: TAU*y*(1/periodEarth - 1/periodMars)
    const closedForm = Math.abs((TAU * 0.5) * (1 / 1.0 - 1 / 1.881));
    expect(Math.abs(Math.abs(earth - mars) - closedForm)).toBeLessThan(1e-9);
  });

  it('keeps every planet at its orbit radius from the sun at 8 sampled times', () => {
    const o = buildOrrery();
    const sunPos = new THREE.Vector3();
    o.group.updateMatrixWorld(true);
    o.group.getObjectByName('sun').getWorldPosition(sunPos);

    for (const arm of o.arms) {
      const planet = arm.node.getObjectByName(`planet-${arm.name}`);
      const world = new THREE.Vector3();
      for (let k = 0; k < 8; k++) {
        setYears(o, (k * 0.25) % 3.7); // 8 arbitrary sample times
        o.group.updateMatrixWorld(true);
        planet.getWorldPosition(world);
        const dist = world.distanceTo(sunPos);
        expect(Math.abs(dist - arm.radius)).toBeLessThan(1e-6);
      }
    }
  });

  it('setYears is stateless: 0.3 then 1 equals 1 directly', () => {
    const a = buildOrrery();
    setYears(a, 0.3);
    setYears(a, 1);

    const b = buildOrrery();
    setYears(b, 1);

    expect(a.arms.length).toBe(b.arms.length);
    for (let i = 0; i < a.arms.length; i++) {
      expect(a.arms[i].node.rotation.y).toBe(b.arms[i].node.rotation.y);
    }
  });

  it('survives a toJSON / ObjectLoader round-trip with arms and radii intact', () => {
    const o = buildOrrery();
    setYears(o, 2.75);

    const json = o.toJSON();
    const parsed = new THREE.ObjectLoader().parse(json);

    // Same number of arm groups.
    const parsedArms = parsed.children.filter(
      (c) => c.userData && c.userData.planet !== undefined
    );
    expect(parsedArms.length).toBe(PLANETS.length);
    expect(o.arms.length).toBe(PLANETS.length);

    // Each arm keeps its planet name, period and orbit radius.
    for (const p of PLANETS) {
      const arm = parsedArms.find((a) => a.userData.planet === p.name);
      expect(arm).toBeDefined();
      expect(arm.userData.period).toBe(p.period);
      expect(arm.userData.radius).toBe(p.radius);

      // Geometry survives too: planet sphere sits at local x = radius.
      const planet = arm.children.find((c) => c.name === `planet-${p.name}`);
      expect(planet).toBeDefined();
      expect(Math.abs(planet.position.x - p.radius)).toBeLessThan(EPS);
    }
  });
});

